{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-0LDFPf/src/uri.js","content":"/**
 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 *
 * A parsed reference is `{ scheme, authority, path, query, fragment }` where
 * `scheme`, `query` and `fragment` are `string | null` (null means absent,
 * `''` means present-but-empty) and `authority` is
 * `null | { userinfo, host, port }` with `userinfo` and `port` following the
 * same null-means-absent convention. `path` is always a string.
 */

export class NoSchemeError extends Error {}
export class PercentError extends Error {}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function indexOfAny(s, chars, from = 0) {
  let min = -1
  for (const c of chars) {
    const i = s.indexOf(c, from)
    if (i !== -1 && (min === -1 || i < min)) min = i
  }
  return min
}

function parseAuthority(raw) {
  if (raw === null) return null
  let rest = raw
  let userinfo = null
  const atIdx = rest.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = rest.slice(0, atIdx)
    rest = rest.slice(atIdx + 1)
  }
  let host = rest
  let port = null
  const bracketIdx = rest.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
  const colonIdx = rest.indexOf(':', searchFrom)
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  }
  return { userinfo, host, port }
}

export function parseReference(s) {
  let rest = s
  let scheme = null
  const schemeEnd = indexOfAny(rest, [':', '/', '?', '#'])
  if (schemeEnd !== -1 && rest[schemeEnd] === ':') {
    scheme = rest.slice(0, schemeEnd)
    rest = rest.slice(schemeEnd + 1)
  }

  let authorityRaw = null
  if (rest.startsWith('//')) {
    const authEnd = indexOfAny(rest, ['/', '?', '#'], 2)
    if (authEnd === -1) {
      authorityRaw = rest.slice(2)
      rest = ''
    } else {
      authorityRaw = rest.slice(2, authEnd)
      rest = rest.slice(authEnd)
    }
  }

  let query = null
  let fragment = null
  const pEnd = indexOfAny(rest, ['?', '#'])
  let path
  if (pEnd === -1) {
    path = rest
    rest = ''
  } else {
    path = rest.slice(0, pEnd)
    rest = rest.slice(pEnd)
  }
  if (rest[0] === '?') {
    const fIdx = rest.indexOf('#')
    if (fIdx === -1) {
      query = rest.slice(1)
      rest = ''
    } else {
      query = rest.slice(1, fIdx)
      rest = rest.slice(fIdx)
    }
  }
  if (rest[0] === '#') {
    fragment = rest.slice(1)
  }

  return { scheme, authority: parseAuthority(authorityRaw), path, query, fragment }
}

function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '/..') {
      input = '/'
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const idx = input[0] === '/' ? input.indexOf('/', 1) : input.indexOf('/')
      const cut = idx === -1 ? input.length : idx
      output += input.slice(0, cut)
      input = input.slice(cut)
    }
  }
  return output
}

function normalizePercent(s, name) {
  if (s === null) return null
  let out = ''
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === '%') {
      const hex = s.slice(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new PercentError(`the ${name} has a truncated percent-encoding`)
      }
      const upperHex = hex.toUpperCase()
      const ch = String.fromCharCode(parseInt(upperHex, 16))
      out += UNRESERVED.test(ch) ? ch : '%' + upperHex
      i += 2
    } else {
      out += c
    }
  }
  return out
}

function lowerAscii(s) {
  if (s === null) return null
  return s.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

function normalizeStruct(u) {
  const scheme = lowerAscii(u.scheme)

  const path0 = normalizePercent(u.path, 'path')
  let authority = null
  if (u.authority !== null) {
    const userinfo = normalizePercent(u.authority.userinfo, 'userinfo')
    const host = lowerAscii(normalizePercent(u.authority.host, 'host'))
    authority = { userinfo, host, port: u.authority.port }
  }
  const query = normalizePercent(u.query, 'query')
  const fragment = normalizePercent(u.fragment, 'fragment')

  if (authority !== null) {
    let port = authority.port
    if (port === '' || (scheme !== null && DEFAULT_PORTS[scheme] === port)) {
      port = null
    }
    authority = { userinfo: authority.userinfo, host: authority.host, port }
  }

  let path = removeDotSegments(path0)
  if (authority !== null && path === '') path = '/'

  return { scheme, authority, path, query, fragment }
}

function serialize(u) {
  let out = ''
  if (u.scheme !== null) out += u.scheme + ':'
  if (u.authority !== null) {
    out += '//'
    if (u.authority.userinfo !== null) out += u.authority.userinfo + '@'
    out += u.authority.host
    if (u.authority.port !== null) out += ':' + u.authority.port
  }
  out += u.path
  if (u.query !== null) out += '?' + u.query
  if (u.fragment !== null) out += '#' + u.fragment
  return out
}

function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

function resolveStruct(base, ref) {
  const target = { fragment: ref.fragment }
  if (ref.scheme !== null) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else if (ref.authority !== null) {
    target.scheme = base.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else if (ref.path === '') {
    target.scheme = base.scheme
    target.authority = base.authority
    target.path = base.path
    target.query = ref.query !== null ? ref.query : base.query
  } else {
    target.scheme = base.scheme
    target.authority = base.authority
    target.path = ref.path.startsWith('/')
      ? removeDotSegments(ref.path)
      : removeDotSegments(mergePaths(base, ref.path))
    target.query = ref.query
  }
  return target
}

export function normalize(str) {
  return serialize(normalizeStruct(parseReference(str)))
}

export function resolve(baseStr, refStr) {
  const base = parseReference(baseStr)
  if (base.scheme === null) {
    throw new NoSchemeError('the base has no scheme')
  }
  const ref = parseReference(refStr)
  return serialize(normalizeStruct(resolveStruct(base, ref)))
}
"}

