{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-0LDFPf/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, resolve } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

const results = []
try {
  lines.forEach((line, index) => {
    const n = index + 1
    if (mode === 'normalize') {
      results.push(normalize(line))
    } else {
      const spaceIdx = line.indexOf(' ')
      if (spaceIdx === -1) {
        throw new Error(`line ${n}: expected a base and a reference`)
      }
      const base = line.slice(0, spaceIdx)
      const ref = line.slice(spaceIdx + 1)
      try {
        results.push(resolve(base, ref))
      } catch (err) {
        throw new Error(`line ${n}: ${err.message}`)
      }
    }
  })
} catch (err) {
  fail(err.message)
}

process.stdout.write(results.map((line) => line + '\n').join(''))
"}

