 * Tokenizer for a formula body (the text following the leading `=`).
 */

export class LexError extends Error {}

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = '^*/+-=<>(),:'

/** Splits a formula body into tokens, or throws `LexError` on an unrecognized character. */
export function tokenize(src) {
  const tokens = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (/[0-9]/.test(ch)) {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i))
      tokens.push({ type: 'NUM', text: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(src.slice(i))
      tokens.push({ type: 'IDENT', text: m[0] })
      i += m[0].length
      continue
    }
    const two = src.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: two, text: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(ch)) {
      tokens.push({ type: ch, text: ch })
      i++
      continue
    }
    throw new LexError(`unexpected character ${ch}`)
  }
  return tokens
}
"}

