{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-52B5XU/src/parser.js","content":"/**
 * Recursive-descent parser turning a formula's tokens into an AST.
 *
 * Precedence, loosest first: comparisons, then `+`/`-`, then `*`/`/`, then
 * `^`, then a leading `-`/`+`. Comparisons and the additive/multiplicative
 * operators group to the left; `^` groups to the right; a leading sign
 * binds tighter than `^`.
 */
import { LexError, tokenize } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }

  parseFormula() {
    const node = this.parseComparison()
    if (this.pos !== this.tokens.length) throw new ParseError('trailing tokens')
    return node
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && COMPARISON_OPS.has(this.peek().type)) {
      const op = this.next().type
      const right = this.parseAdditive()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && (this.peek().type === '+' || this.peek().type === '-')) {
      const op = this.next().type
      const right = this.parseMultiplicative()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && (this.peek().type === '*' || this.peek().type === '/')) {
      const op = this.next().type
      const right = this.parsePower()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek() && this.peek().type === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    const t = this.peek()
    if (t && (t.type === '+' || t.type === '-')) {
      this.next()
      const expr = this.parseUnary()
      return { type: 'unary', op: t.type, expr }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new ParseError('unexpected end of formula')
    if (t.type === 'NUM') {
      this.next()
      return { type: 'number', value: parseFloat(t.text) }
    }
    if (t.type === '(') {
      this.next()
      const e = this.parseComparison()
      this.expect(')')
      return e
    }
    if (t.type === 'IDENT') {
      this.next()
      const name = t.text.toUpperCase()
      if (this.peek() && this.peek().type === '(') {
        this.next()
        const args = this.parseArgList()
        this.expect(')')
        return { type: 'call', name, args }
      }
      if (name === 'TRUE') return { type: 'bool', value: true }
      if (name === 'FALSE') return { type: 'bool', value: false }
      return { type: 'ref', raw: name }
    }
    throw new ParseError(`unexpected token ${t.type}`)
  }

  parseArgList() {
    const args = []
    if (this.peek() && this.peek().type === ')') return args
    args.push(this.parseArgument())
    while (this.peek() && this.peek().type === ',') {
      this.next()
      args.push(this.parseArgument())
    }
    return args
  }

  /** A function argument is either a range written directly, or a full expression. */
  parseArgument() {
    const a = this.peek()
    const b = this.tokens[this.pos + 1]
    const c = this.tokens[this.pos + 2]
    if (a && a.type === 'IDENT' && b && b.type === ':' && c && c.type === 'IDENT') {
      this.pos += 3
      return { type: 'range', from: a.text.toUpperCase(), to: c.text.toUpperCase() }
    }
    return this.parseComparison()
  }
}

/** Parses a formula body into an AST, or throws `ParseError`/`LexError` when the grammar rejects it. */
export function parseFormula(body) {
  const tokens = tokenize(body)
  return new Parser(tokens).parseFormula()
}

export { LexError }
"}

