      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    const t = this.peek()
    if (t && (t.type === '+' || t.type === '-')) {
      this.next()
      const expr = this.parseUnary()
      return { type: 'unary', op: t.type, expr }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new ParseError('unexpected end of formula')
    if (t.type === 'NUM') {
      this.next()
      return { type: 'number', value: parseFloat(t.text) }
    }
    if (t.type === '(') {
      this.next()
      const e = this.parseComparison()
      this.expect(')')
      return e
    }
    if (t.type === 'IDENT') {
      this.next()
      const name = t.text.toUpperCase()
      if (this.peek() && this.peek().type === '(') {
        this.next()
        const args = this.parseArgList()
        this.expect(')')
        return { type: 'call', name, args }
      }
      if (name === 'TRUE') return { type: 'bool', value: true }
      if (name === 'FALSE') return { type: 'bool', value: false }
      return { type: 'ref', raw: name }
    }
    throw new ParseError(`unexpected token ${t.type}`)
  }

  parseArgList() {
    const args = []
    if (this.peek() && this.peek().type === ')') return args
    args.push(this.parseArgument())
    while (this.peek() && this.peek().type === ',') {
      this.next()
      args.push(this.parseArgument())
    }
