  }

  /** A function argument is either a range written directly, or a full expression. */
  parseArgument() {
    const a = this.peek()
    const b = this.tokens[this.pos + 1]
    const c = this.tokens[this.pos + 2]
    if (a && a.type === 'IDENT' && b && b.type === ':' && c && c.type === 'IDENT') {
