import { addressKey, parseStrictAddress } from './address.js'
import { LexError, ParseError, parseFormula } from './parser.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

/**
 * Reads the sheet, returning declared cells keyed by canonical address.
 * Each cell holds its raw content, address, and, for a formula, its parsed
 * AST or a flag that the grammar rejected it. Throws `SheetError` with the
 * exact diagnostic line on an invalid or duplicate address.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    const rest = line.slice(j)
    if (rest === '' || rest[0] === '#') continue

    let k = 0
    while (k < rest.length && rest[k] !== ' ' && rest[k] !== '\t') k++
    const addrToken = rest.slice(0, k)
    let after = rest.slice(k)
    let m = 0
    while (m < after.length && (after[m] === ' ' || after[m] === '\t')) m++
    const content = after.slice(m)

    const addr = parseStrictAddress(addrToken)
    if (!addr) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${addrToken}`)
    }
    const key = addressKey(addr)
    if (cells.has(key)) {
      throw new SheetError(`error: line ${lineNo}: cell ${key} is declared twice`)
    }

    const cell = { key, col: addr.col, row: addr.row, content }
    if (content.startsWith('=')) {
      try {
        cell.ast = parseFormula(content.slice(1))
      } catch (err) {
        if (err instanceof LexError || err instanceof ParseError) cell.parseError = true
        else throw err
      }
    }
    cells.set(key, cell)
  }
  return cells
}
"}

