 * Static dependency collection: walks a formula's AST (independent of
 * evaluation) and gathers every distinct in-range cell it names directly,
 * with ranges expanded.
 */
import { addressKey, compareAddresses, parseStrictAddress, resolveRange } from './address.js'

/** Returns the addresses a parsed formula names, ordered by column then row. */
export function collectRefs(ast) {
  const found = new Map() // key -> { col, row }

  function addAddr(addr) {
    found.set(addressKey(addr), addr)
  }

  function visitArg(node) {
    if (node.type === 'range') {
      const addrs = resolveRange(node.from, node.to)
      if (addrs) for (const addr of addrs) addAddr(addr)
      return
    }
    visit(node)
  }

  function visit(node) {
    switch (node.type) {
      case 'number':
      case 'bool':
        return
      case 'ref': {
        const addr = parseStrictAddress(node.raw)
        if (addr) addAddr(addr)
        return
      }
      case 'unary':
        visit(node.expr)
        return
      case 'binop':
        visit(node.left)
        visit(node.right)
        return
      case 'call':
        for (const arg of node.args) visitArg(arg)
        return
    }
  }

  visit(ast)
  return [...found.values()].sort(compareAddresses)
}
"}

