{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-551KjC/src/uri.js","content":"/**
 * URI reference parsing, normalization and resolution per RFC 3986's
 * generic syntax, following the reduced strict-form rules the CLI asks for.
 */

/** Thrown when a percent-encoding is not followed by two hex digits. */
export class PercentError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/**
 * Splits a URI reference string into its generic-syntax components.
 * Presence and absence are tracked separately from emptiness: hasScheme,
 * hasAuthority, hasQuery and hasFragment are false when the component is
 * absent, even if the corresponding string would otherwise be ''.
 * The authority, when present, is further split into userinfo (null when
 * absent), host and port (hasPort false when absent).
 */
export function parseReference(str) {
  let rest = str
  let hasScheme = false
  let scheme

  let colonIdx = -1
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      colonIdx = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (colonIdx !== -1) {
    hasScheme = true
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
  }

  let hasAuthority = false
  let authority = ''
  if (rest.startsWith('//')) {
    hasAuthority = true
    const afterSlashes = rest.slice(2)
    let end = afterSlashes.length
    for (let i = 0; i < afterSlashes.length; i++) {
      const c = afterSlashes[i]
      if (c === '/' || c === '?' || c === '#') {
        end = i
        break
      }
    }
    authority = afterSlashes.slice(0, end)
    rest = afterSlashes.slice(end)
  }

  const fragmentIdx = rest.indexOf('#')
  const beforeFragment = fragmentIdx === -1 ? rest : rest.slice(0, fragmentIdx)
  let hasFragment = false
  let fragment
  if (fragmentIdx !== -1) {
    hasFragment = true
    fragment = rest.slice(fragmentIdx + 1)
  }

  const queryIdx = beforeFragment.indexOf('?')
  let hasQuery = false
  let query
  let path
  if (queryIdx === -1) {
    path = beforeFragment
  } else {
    path = beforeFragment.slice(0, queryIdx)
    hasQuery = true
    query = beforeFragment.slice(queryIdx + 1)
  }

  let userinfo = null
  let host = ''
  let hasPort = false
  let port = ''
  if (hasAuthority) {
    let a = authority
    const atIdx = a.lastIndexOf('@')
    if (atIdx !== -1) {
      userinfo = a.slice(0, atIdx)
      a = a.slice(atIdx + 1)
    }
    const bracketIdx = a.lastIndexOf(']')
    const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
    const colonIdx2 = a.indexOf(':', searchFrom)
    if (colonIdx2 !== -1) {
      host = a.slice(0, colonIdx2)
      hasPort = true
      port = a.slice(colonIdx2 + 1)
    } else {
      host = a
    }
  }

  return { hasScheme, scheme, hasAuthority, userinfo, host, hasPort, port, path, hasQuery, query, hasFragment, fragment }
}

function isUnreserved(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

/**
 * Uppercases the hex digits of each %XX escape and decodes it when the
 * encoded character is unreserved. Throws PercentError(component) when a
 * '%' is not followed by two hex digits.
 */
function normalizePercentEncoding(str, component) {
  let result = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === '%') {
      const hex = str.slice(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new PercentError(component)
      }
      const upperHex = hex.toUpperCase()
      const ch = String.fromCharCode(parseInt(upperHex, 16))
      result += isUnreserved(ch) ? ch : '%' + upperHex
      i += 2
    } else {
      result += c
    }
  }
  return result
}

function asciiLowerCase(str) {
  let result = ''
  for (const c of str) {
    result += c >= 'A' && c <= 'Z' ? c.toLowerCase() : c
  }
  return result
}

/** Removes '.' and '..' segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.slice(0, output.lastIndexOf('/'))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, output.lastIndexOf('/'))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const idx = input.indexOf('/', 1)
      let segment
      if (idx === -1) {
        segment = input
        input = ''
      } else {
        segment = input.slice(0, idx)
        input = input.slice(idx)
      }
      output += segment
    }
  }
  return output
}

/**
 * Normalizes a parsed URI reference: lowercases the scheme, decodes
 * unreserved percent-encodings and uppercases the rest, lowercases the
 * host, drops a default or empty port, removes dot segments from the
 * path, and forces an empty path to '/' when an authority is present.
 * Percent-encoded components are checked for truncation in the order
 * userinfo, host, path, query, fragment.
 */
export function normalize(p) {
  const result = { ...p }

  if (p.hasScheme) result.scheme = asciiLowerCase(p.scheme)

  if (p.userinfo !== null) result.userinfo = normalizePercentEncoding(p.userinfo, 'userinfo')
  if (p.hasAuthority) result.host = normalizePercentEncoding(p.host, 'host')
  result.path = normalizePercentEncoding(p.path, 'path')
  if (p.hasQuery) result.query = normalizePercentEncoding(p.query, 'query')
  if (p.hasFragment) result.fragment = normalizePercentEncoding(p.fragment, 'fragment')

  if (p.hasAuthority) result.host = asciiLowerCase(result.host)

  if (p.hasAuthority && p.hasPort) {
    const defaultPort = result.hasScheme ? DEFAULT_PORTS[result.scheme] : undefined
    if (p.port === '' || p.port === defaultPort) {
      result.hasPort = false
      result.port = ''
    }
  }

  result.path = removeDotSegments(result.path)

  if (p.hasAuthority && result.path === '') result.path = '/'

  return result
}

/** Serializes a parsed (and typically normalized) URI reference back to a string. */
export function serialize(p) {
  let out = ''
  if (p.hasScheme) out += p.scheme + ':'
  if (p.hasAuthority) {
    out += '//'
    if (p.userinfo !== null) out += p.userinfo + '@'
    out += p.host
    if (p.hasPort) out += ':' + p.port
  }
  out += p.path
  if (p.hasQuery) out += '?' + p.query
  if (p.hasFragment) out += '#' + p.fragment
  return out
}

function authorityOf(p) {
  return { userinfo: p.userinfo, host: p.host, hasPort: p.hasPort, port: p.port }
}

function mergePaths(base, refPath) {
  if (base.hasAuthority && base.path === '') return '/' + refPath
  const lastSlash = base.path.lastIndexOf('/')
  if (lastSlash === -1) return refPath
  return base.path.slice(0, lastSlash + 1) + refPath
}

/**
 * Resolves reference `ref` against base `base` per RFC 3986 section 5.2.2,
 * strict form: a reference that repeats the base's scheme is still treated
 * as an absolute URI. Returns a raw (unnormalized) parsed target; callers
 * normalize the result themselves.
 */
export function resolveReference(base, ref) {
  const target = {}

  if (ref.hasScheme) {
    target.hasScheme = true
    target.scheme = ref.scheme
    target.hasAuthority = ref.hasAuthority
    Object.assign(target, authorityOf(ref))
    target.path = ref.path
    target.hasQuery = ref.hasQuery
    target.query = ref.query
  } else if (ref.hasAuthority) {
    target.hasScheme = base.hasScheme
    target.scheme = base.scheme
    target.hasAuthority = true
    Object.assign(target, authorityOf(ref))
    target.path = ref.path
    target.hasQuery = ref.hasQuery
    target.query = ref.query
  } else if (ref.path === '') {
    target.hasScheme = base.hasScheme
    target.scheme = base.scheme
