{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-551KjC/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseReference, normalize, serialize, resolveReference, PercentError } from './uri.js'

function readStdin() {
  const chunks = []
  process.stdin.on('data', (chunk) => chunks.push(chunk))
  return new Promise((resolve) => {
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

async function main() {
  const args = process.argv.slice(2)
  const mode = args.length === 1 ? args[0] : undefined
  if (mode !== 'normalize' && mode !== 'resolve') {
    fail('usage: cli.js normalize|resolve')
    return
  }

  const input = await readStdin()
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        const parsed = parseReference(line)
        results.push(serialize(normalize(parsed)))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          fail(`line ${lineNo}: expected a base and a reference`)
          return
        }
        const baseStr = line.slice(0, spaceIdx)
        const refStr = line.slice(spaceIdx + 1)
        const base = parseReference(baseStr)
        if (!base.hasScheme) {
          fail(`line ${lineNo}: the base has no scheme`)
          return
        }
        const ref = parseReference(refStr)
        const target = resolveReference(base, ref)
        results.push(serialize(normalize(target)))
      }
    } catch (err) {
      if (err instanceof PercentError) {
        fail(`line ${lineNo}: ${err.message}`)
        return
      }
      throw err
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

