 * Recursive-descent parser for formula bodies, producing an AST. Precedence
 * from loosest to tightest: comparisons, then `+`/`-`, then `*`/`/`, then
 * `^`, then a leading unary sign, which binds tighter than `^` so that
 * `-2^2` parses as `(-2)^2`. Comparisons and the additive/multiplicative
 * operators group to the left; `^` groups to the right.
 *
 * A range (`A1:B3`) is accepted by the grammar in any expression position;
 * whether it sits directly as a function argument is checked afterwards by
 * `findMisplacedRange`, since a misplaced range still needs to be walked
 * for dependencies even though it evaluates to `#ERR!`.
 */
import { tokenize } from './lexer.js'
import { parseAddressWord } from './address.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class ParseError extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  current() {
    return this.tokens[this.pos]
