  advance() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const tok = this.current()
    if (tok.type !== type) throw new ParseError(`expected ${type}`)
    return this.advance()
  }

  parseTop() {
    const expr = this.parseComparison()
    if (this.current().type !== 'EOF') throw new ParseError('trailing tokens')
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.current().type === 'OP' && COMPARISON_OPS.has(this.current().value)) {
      const op = this.advance().value
      const right = this.parseAdditive()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.current().type === 'OP' && (this.current().value === '+' || this.current().value === '-')) {
      const op = this.advance().value
      const right = this.parseMultiplicative()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.current().type === 'OP' && (this.current().value === '*' || this.current().value === '/')) {
      const op = this.advance().value
      const right = this.parsePower()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parsePower() {
    const base = this.parseUnary()
    if (this.current().type === 'OP' && this.current().value === '^') {
      this.advance()
      const right = this.parsePower()
      return { type: 'BinOp', op: '^', left: base, right }
    }
    return base
  }

  parseUnary() {
    if (this.current().type === 'OP' && (this.current().value === '-' || this.current().value === '+')) {
      const op = this.advance().value
      const operand = this.parseUnary()
      return { type: 'UnaryOp', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const tok = this.current()
    if (tok.type === 'NUM') {
      this.advance()
      return { type: 'Number', value: tok.value }
    }
    if (tok.type === 'LP') {
      this.advance()
      const expr = this.parseComparison()
      this.expect('RP')
      return expr
    }
    if (tok.type === 'IDENT') {
      const raw = tok.value
      const hasDigits = /[0-9]/.test(raw)
      if (!hasDigits) {
        const upper = raw.toUpperCase()
        if (upper === 'TRUE' || upper === 'FALSE') {
          this.advance()
          return { type: 'Bool', value: upper === 'TRUE' }
        }
        if (this.tokens[this.pos + 1].type === 'LP') {
          this.advance()
          const args = this.parseArgs()
          return { type: 'Call', name: raw, args }
        }
      }
      this.advance()
      const startInfo = parseAddressWord(raw)
      if (this.current().type === 'COLON') {
        this.advance()
        const endTok = this.current()
        if (endTok.type !== 'IDENT') throw new ParseError('expected address after :')
        this.advance()
        const endInfo = parseAddressWord(endTok.value)
        return { type: 'Range', start: startInfo, end: endInfo }
      }
      return { type: 'Address', ...startInfo }
    }
    throw new ParseError('unexpected token')
  }

  parseArgs() {
    this.expect('LP')
    const args = []
    if (this.current().type === 'RP') {
      this.advance()
      return args
    }
    for (;;) {
      args.push(this.parseComparison())
      if (this.current().type === 'COMMA') {
        this.advance()
        continue
      }
      break
    }
    this.expect('RP')
    return args
  }
}

/**
 * Parses a formula body. Returns { ok:false } when the grammar rejects the
 * text, and { ok:true, ast } otherwise.
 */
export function parseFormula(body) {
  const lexed = tokenize(body)
  if (!lexed.ok) return { ok: false }
  try {
    const ast = new Parser(lexed.tokens).parseTop()
    return { ok: true, ast }
  } catch (e) {
    if (e instanceof ParseError) return { ok: false }
    throw e
  }
}

/**
 * Walks a grammar-accepted AST for a Range node that is not directly a
 * function argument. Such a formula is grammar-accepted (so it is still
 * walked for dependencies) but always evaluates to `#ERR!`.
 */
export function findMisplacedRange(node) {
  return walk(node, false)

  function walk(n, isDirectArg) {
    switch (n.type) {
      case 'Range':
        return !isDirectArg
      case 'Number':
      case 'Bool':
      case 'Address':
        return false
      case 'UnaryOp':
        return walk(n.operand, false)
      case 'BinOp':
        return walk(n.left, false) || walk(n.right, false)
      case 'Call':
        return n.args.some((arg) => walk(arg, true))
      default:
        return false
    }
  }
}
"}

