 * Cell values (number, text, boolean, error) and the arithmetic/comparison
 * rules that combine them.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const ERROR_TOKEN_SET = new Set(ERROR_TOKENS)

export function isErrorLiteral(text) {
  return ERROR_TOKEN_SET.has(text)
}

export function numVal(v) { return { t: 'num', v } }
export function textVal(v) { return { t: 'text', v } }
export function boolVal(v) { return { t: 'bool', v } }
export function errVal(token) { return { t: 'err', v: token } }

/** Rounds to ten significant digits, matching how the sheet prints numbers. */
export function roundToSignificant(x, digits = 10) {
  if (x === 0 || !Number.isFinite(x)) return x
  return parseFloat(x.toPrecision(digits))
}

/** A finite arithmetic result, or `#DIV/0!` for anything not finite. */
export function numResult(x) {
  if (!Number.isFinite(x)) return errVal('#DIV/0!')
  return numVal(x)
}

/** Reads a value as a number for arithmetic; text is not a number. */
export function toNumberStrict(value) {
  if (value.t === 'num') return { n: value.v }
  if (value.t === 'bool') return { n: value.v ? 1 : 0 }
  if (value.t === 'text') return { err: errVal('#VALUE!') }
  return { err: value }
}

const KIND_RANK = { num: 0, text: 1, bool: 2 }

/** -1, 0 or 1: numbers below text below booleans; false below true. */
export function compareValues(a, b) {
  if (a.t !== b.t) return Math.sign(KIND_RANK[a.t] - KIND_RANK[b.t])
  if (a.t === 'num') return Math.sign(a.v - b.v)
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  return Math.sign((a.v ? 1 : 0) - (b.v ? 1 : 0))
}

/** Formats a value the way `values` mode prints it. */
export function formatValue(value) {
  if (value.t === 'num') return String(roundToSignificant(value.v))
  if (value.t === 'text') return value.v
  if (value.t === 'bool') return value.v ? 'TRUE' : 'FALSE'
  return value.v
}
"}

