/**
 * A change describes a run of base lines (`[baseStart, baseEnd)`) replaced by
 * a run of one side's lines (`[sideStart, sideEnd)`). `side` is `'mine'` or
 * `'theirs'`.
 */
function changesFor(base, side, sideName) {
  const matches = lcsMatches(base, side)
  const changes = []
  let prevBase = 0
  let prevSide = 0
  for (const [bi, si] of [...matches, [base.length, side.length]]) {
    if (bi > prevBase || si > prevSide) {
      changes.push({ baseStart: prevBase, baseEnd: bi, sideStart: prevSide, sideEnd: si, side: sideName })
    }
    prevBase = bi + 1
    prevSide = si + 1
  }
  return changes
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * The contiguous range, on one side's own document, corresponding to the
 * given base region: from the smallest start of that side's own changes in
 * the region, moved back to the region's start, to the largest end of its
 * own changes, moved forward to the region's end. A side with no changes in
 * the region is unchanged there, so its lines are the base lines themselves.
 */
function sideLinesForRegion(changesForSide, region, sideDoc, base) {
  if (changesForSide.length === 0) return base.slice(region.start, region.end)
  let minStart = Infinity
  let maxEnd = -Infinity
  let firstChange = null
  let lastChange = null
  for (const c of changesForSide) {
    if (c.baseStart < minStart) {
      minStart = c.baseStart
      firstChange = c
    }
    if (c.baseEnd > maxEnd) {
      maxEnd = c.baseEnd
      lastChange = c
    }
  }
  const sideStart = firstChange.sideStart - (minStart - region.start)
  const sideEnd = lastChange.sideEnd + (region.end - maxEnd)
  return sideDoc.slice(sideStart, sideEnd)
}

/**
 * Splits the base document into an ordered list of regions: stable regions
 * (untouched by either side) and regions touched by one or more changes,
 * each resolved against mine, base and theirs.
 *
 * Each region is one of:
 *   - `{ type: 'stable', lines }`
 *   - `{ type: 'mine' | 'theirs' | 'both', lines }`
 *   - `{ type: 'conflict', mine, base: baseLines, theirs }`
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = changesFor(base, mine, 'mine')
  const theirsChanges = changesFor(base, theirs, 'theirs')
  const combined = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const changeRegions = []
  let idx = 0
  while (idx < combined.length) {
    const region = { start: combined[idx].baseStart, end: combined[idx].baseEnd, changes: [combined[idx]] }
    idx++
    while (idx < combined.length && combined[idx].baseStart <= region.end) {
      region.end = Math.max(region.end, combined[idx].baseEnd)
      region.changes.push(combined[idx])
      idx++
    }
    changeRegions.push(region)
  }

  const ordered = []
  let pos = 0
  for (const region of changeRegions) {
    if (region.start > pos) ordered.push({ start: pos, end: region.start, changes: [] })
    ordered.push(region)
    pos = region.end
  }
  if (pos < base.length) ordered.push({ start: pos, end: base.length, changes: [] })

  return ordered.map(region => resolveRegion(region, mine, base, theirs))
}

function resolveRegion(region, mine, base, theirs) {
  if (region.changes.length === 0) {
    return { type: 'stable', lines: base.slice(region.start, region.end) }
  }
  if (region.changes.length === 1) {
    const c = region.changes[0]
    const doc = c.side === 'mine' ? mine : theirs
    return { type: c.side, lines: doc.slice(c.sideStart, c.sideEnd) }
  }

  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')
  const mineLines = sideLinesForRegion(mineChanges, region, mine, base)
  const theirsLines = sideLinesForRegion(theirsChanges, region, theirs, base)
  const baseLines = base.slice(region.start, region.end)

  if (arraysEqual(mineLines, theirsLines)) return { type: 'both', lines: mineLines }
  if (arraysEqual(mineLines, baseLines)) return { type: 'theirs', lines: theirsLines }
  if (arraysEqual(theirsLines, baseLines)) return { type: 'mine', lines: mineLines }
  return { type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}
"}

