/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { computeRegions } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function splitDocuments(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  return parts
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('error: usage: cli.js merge|merge2|regions')
  }

  const input = readStdin()
  const parts = splitDocuments(input)
  if (parts.length !== 3) {
    fail('error: expected three parts separated by %%%')
  }
  const [mine, base, theirs] = parts

  const regions = computeRegions(mine, base, theirs)
  const hadConflict = regions.some(r => r.type === 'conflict')

  const out = []
  if (mode === 'regions') {
    for (const region of regions) {
      if (region.type === 'conflict') {
        out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}\n`)
      } else {
        out.push(`${region.type} ${region.lines.length}\n`)
      }
    }
  } else {
    for (const region of regions) {
      if (region.type === 'conflict') {
        out.push('<<<<<<< mine\n')
        for (const line of region.mine) out.push(`${line}\n`)
        if (mode === 'merge') {
          out.push('||||||| base\n')
          for (const line of region.base) out.push(`${line}\n`)
        }
        out.push('=======\n')
        for (const line of region.theirs) out.push(`${line}\n`)
        out.push('>>>>>>> theirs\n')
      } else {
        for (const line of region.lines) out.push(`${line}\n`)
      }
    }
  }

  process.stdout.write(out.join(''))
  process.exit(hadConflict ? 1 : 0)
}

main()
"}

