/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { runElection } from './count.js'

function readStdin() {
  const fs = require === undefined ? null : null
  return null
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

async function readAll(stream) {
  const chunks = []
  for await (const chunk of stream) chunks.push(chunk)
  return Buffer.concat(chunks).toString('utf8')
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }

  const input = await readAll(process.stdin)

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      if (err.line === null) fail(err.message)
      else fail(`line ${err.line}: ${err.message}`)
      return
    }
    throw err
  }

  const { rounds, winner } = runElection(election)

  const out = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const parts = round.ordered.map((name) => `${name}=${round.votes.get(name)}`)
      out.push(`round ${index + 1}: ${parts.join(' ')} exhausted=${round.exhausted}`)
      if (round.eliminated !== null) out.push(`eliminated ${round.eliminated}`)
    })
  } else {
    out.push(`rounds ${rounds.length}`)
  }
  out.push(winner !== null ? `winner ${winner}` : 'no winner')

  process.stdout.write(out.join('\n') + '\n')
}

main()
"}

