{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-By2Wn9/src/tokenizer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 */

export class GrammarError extends Error {}

const TOKEN_RE =
  /[ \t]+|[0-9]+(?:\.[0-9]+)?|[A-Za-z]+[0-9]*|<=|>=|<>|[-+*/^=<>(),:]/y

/**
 * Splits a formula body into tokens. Any character that doesn't match a
 * known token shape (including a bare `.` or an unsupported symbol)
 * throws GrammarError, which the caller turns into `#ERR!`.
 */
export function tokenize(body) {
  const tokens = []
  let pos = 0
  TOKEN_RE.lastIndex = 0
  while (pos < body.length) {
    TOKEN_RE.lastIndex = pos
    const m = TOKEN_RE.exec(body)
    if (!m || m.index !== pos) {
      throw new GrammarError(`unexpected character at ${pos}`)
    }
    const text = m[0]
    pos += text.length
    if (/^[ \t]+$/.test(text)) continue
    tokens.push(classify(text))
  }
  return tokens
}

function classify(text) {
  if (/^[0-9]/.test(text)) return { type: 'number', text }
  if (/^[A-Za-z]/.test(text)) return { type: 'word', text }
  return { type: text, text }
}
"}

