import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { compareAddresses, parseAddress } from './address.js'
import { Evaluator } from './evaluate.js'
import { formatValue } from './value.js'
import { directDeps } from './deps.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }

  const source = fs.readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(source)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
