    for (const address of addresses) {
      lines.push(`${address}=${formatValue(evaluator.getValue(address))}`)
    }
  } else {
    for (const address of addresses) {
      const deps = directDeps(cells.get(address))
      lines.push(`${address}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
}

