 * Parses a limiter file into policy declarations, routes and events.
 */

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(lineNo, reason) {
    super(`line ${lineNo}: ${reason}`)
    this.lineNo = lineNo
    this.reason = reason
  }
}

function fail(lineNo, reason) {
  throw new ParseError(lineNo, reason)
}

function parseUint(token, fieldName, min, lineNo) {
  if (!UINT_RE.test(token) || BigInt(token) < min) {
    fail(lineNo, `${fieldName} must be an integer of at least ${min}`)
  }
  return BigInt(token)
}

function requireName(token, lineNo, kind) {
  if (!NAME_RE.test(token)) {
    fail(lineNo, `invalid ${kind} ${token}`)
  }
  return token
}

/**
 * @param {string} input raw stdin content
 * @returns {{ policies: Map<string, object>, routes: Array<object>, events: Array<object> }}
 */
export function parseInput(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const policies = new Map()
  const routes = []
  const routesByPrefix = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) {
        fail(lineNo, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const name = requireName(tokens[1], lineNo, 'policy name')
      const capacity = parseUint(tokens[2], 'capacity', 1n, lineNo)
      const refill = parseUint(tokens[3], 'refill', 0n, lineNo)
      const per = parseUint(tokens[4], 'per', 1n, lineNo)
      if (policies.has(name)) {
        fail(lineNo, `policy ${name} is declared twice`)
      }
      policies.set(name, { type: 'bucket', name, capacity, refill, per })
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        fail(lineNo, 'expected window <name> <limit> <span>')
      }
      const name = requireName(tokens[1], lineNo, 'policy name')
      const limit = parseUint(tokens[2], 'limit', 0n, lineNo)
      const span = parseUint(tokens[3], 'span', 1n, lineNo)
      if (policies.has(name)) {
        fail(lineNo, `policy ${name} is declared twice`)
      }
      policies.set(name, { type: 'window', name, limit, span })
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        fail(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = requireName(tokens[1], lineNo, 'route prefix')
      const policyNames = tokens.slice(2)
      for (const policyName of policyNames) {
        if (!policies.has(policyName)) {
          fail(lineNo, `unknown policy ${policyName}`)
        }
      }
      if (routesByPrefix.has(prefix)) {
        fail(lineNo, `prefix ${prefix} is routed twice`)
      }
      const route = { prefix, policies: policyNames }
      routesByPrefix.set(prefix, route)
      routes.push(route)
    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        fail(lineNo, 'expected event <tick> <key>')
      }
      const tick = parseUint(tokens[1], 'tick', 0n, lineNo)
      const key = requireName(tokens[2], lineNo, 'key')
      if (lastTick !== null && tick < lastTick) {
        fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      seenEvent = true
      events.push({ tick, key, lineNo })
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

