/**
 * Builds the runtime policy instances from parsed declarations, and finds,
 * for a given key, the route with the longest matching prefix.
 */
function buildPolicyInstances(policies) {
  const instances = new Map()
  for (const [name, decl] of policies) {
    instances.set(name, decl.type === 'bucket' ? new BucketPolicy(decl) : new WindowPolicy(decl))
  }
  return instances
}

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) {
        best = route
      }
    }
  }
  return best
}

/**
 * Replays every event against the declared policies and routes.
 *
 * @returns {Array<{ tick: bigint, key: string, allow: boolean, denyPolicy: string|null }>}
 */
export function simulate({ policies, routes, events }) {
  const instances = buildPolicyInstances(policies)
  const results = []

  for (const { tick, key } of events) {
    const route = findRoute(routes, key)
    if (route === null) {
      results.push({ tick, key, allow: true, denyPolicy: null })
      continue
    }

    const policyInstances = route.policies.map((name) => instances.get(name))
    for (const policy of policyInstances) {
      policy.advance(key, tick)
    }

    let denyPolicy = null
    for (let i = 0; i < policyInstances.length; i++) {
      if (!policyInstances[i].allows(key)) {
        denyPolicy = route.policies[i]
        break
      }
    }

    if (denyPolicy === null) {
      for (const policy of policyInstances) {
        policy.record(key, tick)
      }
      results.push({ tick, key, allow: true, denyPolicy: null })
    } else {
      results.push({ tick, key, allow: false, denyPolicy })
    }
  }

  return results
}
"}

