{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-FUVkd5/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { parseInput, ParseError } from './parse.js'
import { simulate } from './simulate.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function renderReplay(results) {
  const lines = []
  for (const r of results) {
    lines.push(r.allow ? `${r.tick} ${r.key} allow` : `${r.tick} ${r.key} deny ${r.denyPolicy}`)
  }
  return lines
}

function renderSummary(results) {
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0
  for (const r of results) {
    let stats = perKey.get(r.key)
    if (stats === undefined) {
      stats = { allowed: 0, denied: 0 }
      perKey.set(r.key, stats)
    }
    if (r.allow) {
      stats.allowed++
      totalAllowed++
    } else {
      stats.denied++
      totalDenied++
    }
  }
  const keys = [...perKey.keys()].sort()
  const lines = keys.map((key) => {
    const stats = perKey.get(key)
    return `${key} allowed=${stats.allowed} denied=${stats.denied}`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let parsed
  try {
    parsed = parseInput(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const results = simulate(parsed)
  const lines = mode === 'replay' ? renderReplay(results) : renderSummary(results)
  process.stdout.write(lines.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

