{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-HinbSf/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { CliError, parseElection } from './parser.js'
import { runElection } from './election.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatRoundLine(index, round) {
  const entries = [...round.votes.entries()].sort(([nameA, countA], [nameB, countB]) => {
    if (countA !== countB) return countA > countB ? -1 : 1
    return nameA < nameB ? -1 : 1
  })
  const field = entries.map(([name, count]) => `${name}=${count}`).join(' ')
  return `round ${index}: ${field} exhausted=${round.exhausted}`
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let election
  try {
    const { candidates, ballots } = parseElection(input)
    election = runElection(candidates, ballots)
  } catch (err) {
    if (err instanceof CliError) {
      fail(err.line === null ? err.message : `line ${err.line}: ${err.message}`)
      return
    }
    throw err
  }

  const { rounds, winner } = election
  const outcome = winner === null ? 'no winner' : `winner ${winner}`
  const lines = []

  if (mode === 'rounds') {
    rounds.forEach((round, i) => {
      lines.push(formatRoundLine(i + 1, round))
      if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
    })
  } else {
    lines.push(`rounds ${rounds.length}`)
  }
  lines.push(outcome)

  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

