 * A hand-written scanner for the toy language described by the task. It
 * turns UTF-8 source text into a flat list of tokens, tracking 1-based
 * line/column positions per code point as it goes.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

const isLetter = (c) => typeof c === 'string' && /[A-Za-z]/.test(c)
const isDigit = (c) => typeof c === 'string' && /[0-9]/.test(c)
const isIdentStart = (c) => isLetter(c) || c === '_'
const isIdentPart = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHexDigit = (c) => typeof c === 'string' && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => typeof c === 'string' && /[0-7]/.test(c)

/** Raised for any scanning failure; carries the 1-based position to report. */
class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

class Lexer {
  constructor(source) {
    this.cps = Array.from(source)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  peek(offset = 0) {
    return this.cps[this.i + offset]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  atEnd() {
    return this.i >= this.cps.length
  }

  /** Consume and return one code point, updating line/column per the spec's rules. */
  advance() {
    const ch = this.cps[this.i]
    const cp = ch.codePointAt(0)
    if (cp === 0x0a) {
      this.line += 1
      this.col = 1
    } else if (cp === 0x09) {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col += 1
    }
    this.i += 1
    return ch
  }

  textSince(startIdx) {
    return this.cps.slice(startIdx, this.i).join('')
  }

  error(pos, reason) {
    return new LexError(pos.line, pos.col, reason)
  }

  tokenize() {
    const tokens = []
    for (;;) {
      while (!this.atEnd() && /[ \t\r\n]/.test(this.peek())) this.advance()
      if (this.atEnd()) break

      if (this.peek() === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }
      if (this.peek() === 'r' && this.peek(1) === '"') {
        tokens.push(this.scanRawString())
        continue
      }
      if (this.peek() === '"') {
        tokens.push(this.scanString())
        continue
      }
      if (isIdentStart(this.peek())) {
        tokens.push(this.scanIdent())
        continue
      }
      if (isDigit(this.peek())) {
        tokens.push(this.scanNumber())
        continue
      }
      tokens.push(this.scanPunct())
    }
    return tokens
  }

  skipLineComment() {
    while (!this.atEnd() && this.peek() !== '\n') this.advance()
  }

  skipBlockComment() {
    const startPos = this.pos()
    this.advance()
    this.advance()
    let depth = 1
    while (depth > 0) {
      if (this.atEnd()) throw this.error(startPos, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth += 1
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth -= 1
      } else {
        this.advance()
      }
    }
  }

  scanIdent() {
    const startPos = this.pos()
    const startIdx = this.i
    this.advance()
    while (isIdentPart(this.peek())) this.advance()
    const text = this.textSince(startIdx)
    return { kind: KEYWORDS.has(text) ? 'keyword' : 'ident', text, pos: startPos }
  }

