   * Consumes a maximal run of digits valid for `isValidDigit`, allowing a
   * single `_` between two digits of the run. Returns the number of digits
   * consumed (not counting underscores), leaving the cursor just past the
   * run on return.
   */
  scanDigitRun(isValidDigit) {
    let count = 0
    for (;;) {
      if (isValidDigit(this.peek())) {
        this.advance()
        count += 1
      } else if (this.peek() === '_' && count > 0 && isValidDigit(this.peek(1))) {
        this.advance()
      } else {
        break
      }
    }
    return count
  }

  scanNumber() {
    const startPos = this.pos()
    const startIdx = this.i
    let prefixNoDigit = false

    if (this.peek() === '0' && /[xXbBoO]/.test(this.peek(1))) {
      const base = this.peek(1).toLowerCase()
      this.advance()
      this.advance()
      const validator = base === 'x' ? isHexDigit : base === 'b' ? isBinDigit : isOctDigit
      const count = this.scanDigitRun(validator)
      if (count === 0) prefixNoDigit = true
    } else {
      this.scanDigitRun(isDigit)
      if (this.peek() === '.' && isDigit(this.peek(1))) {
        this.advance()
        this.scanDigitRun(isDigit)
      }
      if (this.peek() === 'e' || this.peek() === 'E') {
        const hasSign = this.peek(1) === '+' || this.peek(1) === '-'
        const afterSign = hasSign ? this.peek(2) : this.peek(1)
        if (isDigit(afterSign)) {
          this.advance()
          if (hasSign) this.advance()
          this.scanDigitRun(isDigit)
        }
      }
    }

    let trailingConsumed = false
    while (isIdentPart(this.peek())) {
      this.advance()
      trailingConsumed = true
    }

    if (prefixNoDigit || trailingConsumed) {
      throw this.error(startPos, `invalid number ${this.textSince(startIdx)}`)
    }
    return { kind: 'number', text: this.textSince(startIdx), pos: startPos }
  }

  scanString() {
    const startPos = this.pos()
    this.advance()
    let value = ''
    for (;;) {
      if (this.atEnd()) throw this.error(startPos, 'unterminated string')
      const ch = this.peek()
      if (ch === '"') {
        this.advance()
        break
      }
      if (ch === '\n') throw this.error(this.pos(), 'newline in string')
      if (ch === '\\') {
        const bsPos = this.pos()
        this.advance()
        if (this.atEnd()) throw this.error(startPos, 'unterminated string')
        value += this.scanEscape(startPos, bsPos)
        continue
      }
      value += ch
      this.advance()
    }
    return { kind: 'string', value, pos: startPos }
  }

  scanEscape(startPos, bsPos) {
    const esc = this.peek()
    const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '\0': '\0', 0: '\0' }
    if (Object.prototype.hasOwnProperty.call(simple, esc)) {
      this.advance()
      return simple[esc]
    }
    if (esc === 'x') {
      this.advance()
      let hex = ''
      for (let k = 0; k < 2; k += 1) {
        if (this.atEnd()) throw this.error(startPos, 'unterminated string')
        const c = this.peek()
        if (!isHexDigit(c)) throw this.error(bsPos, 'invalid escape \\x')
        hex += c
        this.advance()
      }
      return String.fromCharCode(parseInt(hex, 16))
    }
    if (esc === 'u') {
      this.advance()
      if (this.atEnd()) throw this.error(startPos, 'unterminated string')
      if (this.peek() !== '{') throw this.error(bsPos, 'invalid escape \\u')
      this.advance()
      let hex = ''
      for (;;) {
        if (this.atEnd()) throw this.error(startPos, 'unterminated string')
        const c = this.peek()
        if (c === '}') break
        if (!isHexDigit(c)) throw this.error(bsPos, 'invalid escape \\u')
        hex += c
        this.advance()
      }
      if (hex.length === 0) throw this.error(bsPos, 'invalid escape \\u')
      this.advance()
      const cp = parseInt(hex, 16)
      if (cp > 0x10ffff) throw this.error(bsPos, 'invalid escape \\u')
      return String.fromCodePoint(cp)
    }
    throw this.error(bsPos, `invalid escape \\${esc}`)
  }

  scanRawString() {
    const startPos = this.pos()
    this.advance()
    this.advance()
    let value = ''
    for (;;) {
      if (this.atEnd()) throw this.error(startPos, 'unterminated string')
      const ch = this.peek()
      if (ch === '"') {
        this.advance()
        break
      }
      value += ch
      this.advance()
    }
    return { kind: 'rawstring', value, pos: startPos }
  }

  scanPunct() {
    const startPos = this.pos()
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    if (PUNCT2.has(two)) {
      this.advance()
      this.advance()
      return { kind: 'punct', text: two, pos: startPos }
    }
    const one = this.peek()
    if (PUNCT1.has(one)) {
      this.advance()
      return { kind: 'punct', text: one, pos: startPos }
    }
    throw this.error(startPos, `unexpected character ${one}`)
  }
}

export function tokenize(source) {
  return new Lexer(source).tokenize()
}

export { LexError }
"}

