          this.advance()
          if (hasSign) this.advance()
          this.scanDigitRun(isDigit)
        }
      }
    }

    let trailingConsumed = false
    while (isIdentPart(this.peek())) {
      this.advance()
      trailingConsumed = true
    }

    if (prefixNoDigit || trailingConsumed) {
      throw this.error(startPos, `invalid number ${this.textSince(startIdx)}`)
    }
    return { kind: 'number', text: this.textSince(startIdx), pos: startPos }
  }

  scanString() {
    const startPos = this.pos()
    this.advance()
    let value = ''
    for (;;) {
      if (this.atEnd()) throw this.error(startPos, 'unterminated string')
      const ch = this.peek()
      if (ch === '"') {
        this.advance()
        break
      }
      if (ch === '\n') throw this.error(this.pos(), 'newline in string')
      if (ch === '\\') {
        const bsPos = this.pos()
        this.advance()
        if (this.atEnd()) throw this.error(startPos, 'unterminated string')
        value += this.scanEscape(startPos, bsPos)
        continue
      }
      value += ch
      this.advance()
    }
    return { kind: 'string', value, pos: startPos }
  }

  scanEscape(startPos, bsPos) {
    const esc = this.peek()
    const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '\0': '\0', 0: '\0' }
    if (Object.prototype.hasOwnProperty.call(simple, esc)) {
      this.advance()
      return simple[esc]
    }
    if (esc === 'x') {
      this.advance()
      let hex = ''
      for (let k = 0; k < 2; k += 1) {
        if (this.atEnd()) throw this.error(startPos, 'unterminated string')
        const c = this.peek()
        if (!isHexDigit(c)) throw this.error(bsPos, 'invalid escape \\x')
        hex += c
        this.advance()
      }
      return String.fromCharCode(parseInt(hex, 16))
    }
    if (esc === 'u') {
      this.advance()
      if (this.atEnd()) throw this.error(startPos, 'unterminated string')
      if (this.peek() !== '{') throw this.error(bsPos, 'invalid escape \\u')
      this.advance()
      let hex = ''
      for (;;) {
        if (this.atEnd()) throw this.error(startPos, 'unterminated string')
        const c = this.peek()
        if (c === '}') break
        if (!isHexDigit(c)) throw this.error(bsPos, 'invalid escape \\u')
        hex += c
        this.advance()
      }
      if (hex.length === 0) throw this.error(bsPos, 'invalid escape \\u')
      this.advance()
      const cp = parseInt(hex, 16)
      if (cp > 0x10ffff) throw this.error(bsPos, 'invalid escape \\u')
      return String.fromCodePoint(cp)
    }
    throw this.error(bsPos, `invalid escape \\${esc}`)
  }

  scanRawString() {
    const startPos = this.pos()
    this.advance()
    this.advance()
    let value = ''
    for (;;) {
      if (this.atEnd()) throw this.error(startPos, 'unterminated string')
      const ch = this.peek()
      if (ch === '"') {
        this.advance()
        break
      }
      value += ch
      this.advance()
    }
    return { kind: 'rawstring', value, pos: startPos }
  }

  scanPunct() {
    const startPos = this.pos()
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    if (PUNCT2.has(two)) {
      this.advance()
      this.advance()
      return { kind: 'punct', text: two, pos: startPos }
    }
    const one = this.peek()
    if (PUNCT1.has(one)) {
      this.advance()
      return { kind: 'punct', text: one, pos: startPos }
    }
    throw this.error(startPos, `unexpected character ${one}`)
  }
}

export function tokenize(source) {
  return new Lexer(source).tokenize()
}

export { LexError }
"}

