        case '"':
          out += '"'
          j += 2
          break
        case '\\':
          out += '\\'
          j += 2
          break
        case 'n':
          out += '\n'
          j += 2
          break
        case 't':
          out += '\t'
          j += 2
          break
        case 'r':
          out += '\r'
          j += 2
          break
