    if (!container.keys.has(name)) {
      const t = tableNode()
      container.keys.set(name, t)
      container = t
    } else {
      const existing = container.keys.get(name)
      if (existing.kind === 'array' && existing.isArrayOfTables) {
        container = existing.items[existing.items.length - 1]
      } else if (existing.kind === 'table') {
        container = existing
      } else {
        throw new LineError(`${path} is not a table`)
      }
    }
  }
  return container
}

function handleSingleHeader(doc, names) {
  const container = walkToContainer(doc.root, names, [])
  const lastName = names[names.length - 1]
  const fullPath = buildPath(names)
  if (!container.keys.has(lastName)) {
    const t = tableNode()
    t.explicit = true
    container.keys.set(lastName, t)
    doc.current = t
  } else {
    const existing = container.keys.get(lastName)
    if (existing.kind !== 'table') {
      throw new LineError(`${fullPath} is not a table`)
    }
    if (existing.explicit) {
      throw new LineError(`table ${fullPath} is defined twice`)
    }
    existing.explicit = true
    doc.current = existing
  }
  doc.currentPath = names
}

function handleDoubleHeader(doc, names) {
  const container = walkToContainer(doc.root, names, [])
  const lastName = names[names.length - 1]
  const fullPath = buildPath(names)
  let arr
  if (!container.keys.has(lastName)) {
    arr = arrayNode([], true)
    container.keys.set(lastName, arr)
  } else {
    arr = container.keys.get(lastName)
    if (!(arr.kind === 'array' && arr.isArrayOfTables)) {
      throw new LineError(`${fullPath} is not an array of tables`)
    }
  }
  const t = tableNode()
  arr.items.push(t)
  doc.current = t
  doc.currentPath = names
}

function handleHeaderLine(doc, s, i) {
  let double = false
  let j = i + 1
  if (s[j] === '[') {
    double = true
    j++
  }
  const sig = significant(s, j)
  if (sig === -1) throw new LineError('unterminated table header')
  const { names, next } = parseDottedName(s, sig)
  j = next

  const sigClose = significant(s, j)
  if (sigClose === -1) throw new LineError('unterminated table header')
  if (double) {
    if (s[sigClose] === ']' && s[sigClose + 1] === ']') {
      j = sigClose + 2
    } else {
      throw new LineError('unterminated table header')
    }
  } else {
    if (s[sigClose] === ']') {
      j = sigClose + 1
    } else {
