  const k = skipWS(s, 0)
  if (k >= s.length) return
  if (s[k] === '#' || s[k] === ';') return
  if (s[k] === '[') {
    handleHeaderLine(doc, s, k)
    return
  }
  handleKeyValueLine(doc, s, k)
