{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import fs from 'node:fs'
import { computeSegments } from './regions.js'

const MODES = ['merge', 'merge2', 'regions']

/**
 * Split raw text on newlines, dropping the empty line a trailing newline
 * leaves behind.
 */
function splitLines(raw) {
  if (raw === '') return []
  const lines = raw.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

/** Split lines into documents at every line that is exactly `%%%`. */
function splitDocuments(lines) {
  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }
  return docs
}

/** Render a resolved region or stable run as merge/merge2 output lines. */
function renderSegment(segment, mode) {
  if (segment.type === 'stable' || segment.kind !== 'conflict') return { lines: segment.lines, conflict: false }
  const lines = ['<<<<<<< mine', ...segment.mineLines]
  if (mode === 'merge') lines.push('||||||| base', ...segment.baseLines)
  lines.push('=======', ...segment.theirsLines, '>>>>>>> theirs')
  return { lines, conflict: true }
}

/** Render a segment as a `regions` mode summary line. */
function renderRegionLine(segment) {
  if (segment.type === 'stable') return { line: `stable ${segment.lines.length}`, conflict: false }
  if (segment.kind === 'conflict') {
    const { mineLines, baseLines, theirsLines } = segment
    return { line: `conflict mine=${mineLines.length} base=${baseLines.length} theirs=${theirsLines.length}`, conflict: true }
  }
  return { line: `${segment.kind} ${segment.lines.length}`, conflict: false }
}

function joinLines(lines) {
  return lines.length === 0 ? '' : `${lines.join('\n')}\n`
}

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (!MODES.includes(mode)) fail('error: usage: cli.js merge|merge2|regions')

  const raw = fs.readFileSync(0, 'utf8')
  const docs = splitDocuments(splitLines(raw))
  if (docs.length !== 3) fail('error: expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const segments = computeSegments(mine, base, theirs)
  let conflictFound = false
  let output

  if (mode === 'regions') {
    const rendered = segments.map(renderRegionLine)
    conflictFound = rendered.some(entry => entry.conflict)
    output = joinLines(rendered.map(entry => entry.line))
  } else {
    const rendered = segments.map(segment => renderSegment(segment, mode))
    conflictFound = rendered.some(entry => entry.conflict)
    output = joinLines(rendered.flatMap(entry => entry.lines))
  }

  process.stdout.write(output)
  process.exit(conflictFound ? 1 : 0)
}

main()
"}

