{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-WgwgCC/src/uri.js","content":"/**
 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 *
 * A parsed reference is `{ scheme, authority, path, query, fragment }`.
 * `scheme`, `query` and `fragment` are `string | null` (null means the
 * component is absent, as opposed to written empty). `authority` is
 * `null | { userinfo, host, port }`, where `userinfo` and `port` are
 * `string | null` and `host` is always a `string`. `path` is always a
 * `string` (the empty path is written `''`).
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

const HEX_PAIR = /^[0-9a-fA-F]{2}$/
const UNRESERVED = /[A-Za-z0-9\-._~]/

/** Thrown when a `%` is not followed by two hexadecimal digits. */
export class TruncatedPercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

/** Split a URI reference into its generic-syntax components. */
export function parseReference(s) {
  let i = 0
  let scheme = null
  const colon = s.indexOf(':')
  if (colon !== -1 && !/[/?#]/.test(s.slice(0, colon))) {
    scheme = s.slice(0, colon)
    i = colon + 1
  }

  let authority = null
  if (s.slice(i, i + 2) === '//') {
    i += 2
    let end = i
    while (end < s.length && s[end] !== '/' && s[end] !== '?' && s[end] !== '#') end++
    authority = parseAuthority(s.slice(i, end))
    i = end
  }

  let pathEnd = i
  while (pathEnd < s.length && s[pathEnd] !== '?' && s[pathEnd] !== '#') pathEnd++
  const path = s.slice(i, pathEnd)
  i = pathEnd

  let query = null
  if (s[i] === '?') {
    i++
    let queryEnd = i
    while (queryEnd < s.length && s[queryEnd] !== '#') queryEnd++
    query = s.slice(i, queryEnd)
    i = queryEnd
  }

  let fragment = null
  if (s[i] === '#') {
    fragment = s.slice(i + 1)
  }

  return { scheme, authority, path, query, fragment }
}

function parseAuthority(a) {
  const at = a.lastIndexOf('@')
  let userinfo = null
  let hostport = a
  if (at !== -1) {
    userinfo = a.slice(0, at)
    hostport = a.slice(at + 1)
  }
  const bracket = hostport.lastIndexOf(']')
  const searchFrom = bracket === -1 ? 0 : bracket + 1
  const colon = hostport.indexOf(':', searchFrom)
  let host = hostport
  let port = null
  if (colon !== -1) {
    host = hostport.slice(0, colon)
    port = hostport.slice(colon + 1)
  }
