{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-cR5DjO/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseElection } from './parse.js'
import { runElection } from './election.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}
const mode = args[0]

const input = readFileSync(0, 'utf8')

let election
try {
  election = parseElection(input)
} catch (err) {
  if (!(err instanceof CliError)) throw err
  process.stderr.write(err.message + '\n')
  process.exit(2)
}

const { rounds, winner } = runElection(election)

let output = ''
if (mode === 'rounds') {
  rounds.forEach((round, index) => {
    const entries = round.entries.map((e) => `${e.name}=${e.count}`).join(' ')
    output += `round ${index + 1}: ${entries} exhausted=${round.exhausted}\n`
    if (round.eliminated !== null) output += `eliminated ${round.eliminated}\n`
  })
} else {
  output += `rounds ${rounds.length}\n`
}
output += winner !== null ? `winner ${winner}\n` : 'no winner\n'

process.stdout.write(output)
process.exit(0)
"}

