import { isBlankLine, parseLine, newTable } from './line-parser.js'

/** Parses a whole configuration document into its root table node. */
export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable([], true)
  let current = root

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (isBlankLine(line)) continue
    try {
      current = parseLine(line, root, current)
    } catch (e) {
      if (e instanceof ConfigError) throw new DocError(i + 1, e.message)
      throw e
    }
  }

  return root
}
"}

