 * Replays a parsed program's events against its policies and returns one
 * verdict per event, in log order.
 */
export function simulate(program) {
  const { policies, routes, events } = program
  const routeCache = new Map()

  function resolveRoute(key) {
    if (routeCache.has(key)) return routeCache.get(key)
    let best = null
    for (const route of routes) {
      if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
        best = route
      }
    }
    const policyNames = best ? best.policyNames : []
    routeCache.set(key, policyNames)
    return policyNames
  }

  const results = []
  for (const { tick, key } of events) {
    const policyNames = resolveRoute(key)
    if (policyNames.length === 0) {
      results.push({ tick, key, verdict: 'allow' })
      continue
    }

    const instances = policyNames.map((name) => policies.get(name))
    for (const instance of instances) instance.advance(key, tick)

    let deniedBy = null
    for (let i = 0; i < instances.length; i++) {
      if (!instances[i].allow(key)) {
        deniedBy = policyNames[i]
        break
      }
    }

    if (deniedBy === null) {
      for (const instance of instances) instance.record(key)
      results.push({ tick, key, verdict: 'allow' })
    } else {
      results.push({ tick, key, verdict: 'deny', policy: deniedBy })
    }
  }
  return results
}
"}

