/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { ParseError } from './errors.js'
import { parseProgram } from './parse.js'
import { simulate } from './simulate.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let program
  try {
    program = parseProgram(input)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(`line ${err.line}: ${err.message}`)
    }
    throw err
  }

  const results = simulate(program)

  if (mode === 'replay') {
    let out = ''
    for (const r of results) {
      out += r.verdict === 'allow' ? `${r.tick} ${r.key} allow\n` : `${r.tick} ${r.key} deny ${r.policy}\n`
    }
    process.stdout.write(out)
  } else {
    const totals = new Map()
    let totalAllowed = 0
    let totalDenied = 0
    for (const r of results) {
      let t = totals.get(r.key)
      if (!t) {
        t = { allowed: 0, denied: 0 }
        totals.set(r.key, t)
      }
      if (r.verdict === 'allow') {
        t.allowed++
        totalAllowed++
      } else {
        t.denied++
        totalDenied++
      }
    }
    const keys = Array.from(totals.keys()).sort()
    let out = ''
    for (const key of keys) {
      const t = totals.get(key)
      out += `${key} allowed=${t.allowed} denied=${t.denied}\n`
    }
    out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
    process.stdout.write(out)
  }

  process.exit(0)
}

main()
"}

