{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-hGmq12/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { buildMergeSegments } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Splits raw input into lines, dropping the empty tail a trailing newline leaves. */
function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/** Splits the input's lines into the three documents separated by `%%%` lines. */
function splitDocuments(lines) {
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  if (parts.length !== 3) fail('expected three parts separated by %%%')
  return parts
}

function renderConflict(out, mineLines, baseLines, theirsLines, includeBase) {
  out.push('<<<<<<< mine')
  out.push(...mineLines)
  if (includeBase) {
    out.push('||||||| base')
    out.push(...baseLines)
  }
  out.push('=======')
  out.push(...theirsLines)
  out.push('>>>>>>> theirs')
}

function runMerge(segments, includeBase) {
  const out = []
  let conflict = false
  for (const segment of segments) {
    if (segment.type === 'stable' || segment.kind !== 'conflict') {
      out.push(...(segment.type === 'stable' ? segment.lines : segment.resolvedLines))
    } else {
      conflict = true
      renderConflict(out, segment.mineLines, segment.baseLines, segment.theirsLines, includeBase)
    }
  }
  return { text: out.length > 0 ? `${out.join('\n')}\n` : '', conflict }
}

function runRegions(segments) {
  const out = []
  let conflict = false
  for (const segment of segments) {
    if (segment.type === 'stable') {
      out.push(`stable ${segment.lines.length}`)
    } else if (segment.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${segment.mineLines.length} base=${segment.baseLines.length} theirs=${segment.theirsLines.length}`)
    } else {
      out.push(`${segment.kind} ${segment.resolvedLines.length}`)
    }
  }
  return { text: out.length > 0 ? `${out.join('\n')}\n` : '', conflict }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  const [mine, base, theirs] = splitDocuments(splitLines(input))

  const segments = buildMergeSegments(mine, base, theirs)
  const { text, conflict } =
    mode === 'regions' ? runRegions(segments) : runMerge(segments, mode === 'merge')

  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()
"}

