 * Rendering of a parsed document: `toJSON` for canonical JSON, `toKeys` for
 * the one-path-per-line listing.
 */

function typeName(value) {
  return value.t
}

function serializeTable(node, indent) {
  const keys = [...node.entries.keys()].sort()
  if (keys.length === 0) return '{}'
  const pad = ' '.repeat(indent + 2)
  const inner = keys
    .map((k) => `${pad}${JSON.stringify(k)}: ${serializeValue(node.entries.get(k), indent + 2)}`)
    .join(',\n')
  return `{\n${inner}\n${' '.repeat(indent)}}`
}

function serializeArray(items, indent) {
  if (items.length === 0) return '[]'
  const pad = ' '.repeat(indent + 2)
  const inner = items.map((it) => `${pad}${serializeValue(it, indent + 2)}`).join(',\n')
  return `[\n${inner}\n${' '.repeat(indent)}]`
}

function serializeValue(value, indent) {
  switch (value.t) {
    case 'table':
      return serializeTable(value.v, indent)
    case 'array':
      return serializeArray(value.v, indent)
    case 'string':
      return JSON.stringify(value.v)
    case 'integer':
      return value.v.toString()
    case 'float':
      return JSON.stringify(value.v)
    case 'boolean':
      return value.v ? 'true' : 'false'
    default:
      throw new Error(`unreachable value tag ${value.t}`)
  }
}

export function toJSON(root) {
  return serializeTable(root, 0) + '\n'
}

function walkTable(node, path, lines) {
  const keys = [...node.entries.keys()].sort()
  for (const k of keys) {
    const child = node.entries.get(k)
    const childPath = path === '' ? k : `${path}.${k}`
    lines.push(`${childPath} ${typeName(child)}`)
    walkValue(child, childPath, lines)
  }
}

function walkValue(value, path, lines) {
  if (value.t === 'table') {
    walkTable(value.v, path, lines)
  } else if (value.t === 'array') {
    value.v.forEach((item, i) => {
      const childPath = `${path}[${i}]`
      lines.push(`${childPath} ${typeName(item)}`)
      walkValue(item, childPath, lines)
    })
  }
}

export function toKeys(root) {
  const lines = []
  walkTable(root, '', lines)
  return lines.map((l) => `${l}\n`).join('')
}
"}

{"file_path":"./src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { parseDocument, ParseError } from './parser.js'
import { toJSON, toKeys } from './format.js'

const mode = process.argv[2]
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')

try {
  const root = parseDocument(input)
  const output = mode === 'json' ? toJSON(root) : toKeys(root)
  process.stdout.write(output)
  process.exit(0)
} catch (err) {
  if (err instanceof ParseError) {
    process.stderr.write(`error: line ${err.line}: ${err.reason}\n`)
    process.exit(2)
  }
  throw err
}
"}

