/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { LineError } from './validate.js'
import { run } from './engine.js'

function usageError() {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    usageError()
    return
  }
  const mode = args[0]
  const input = readFileSync(0, 'utf8')

  let events
  try {
    events = run(input)
  } catch (err) {
    if (err instanceof LineError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
      return
    }
    throw err
  }

  if (mode === 'replay') {
    let out = ''
    for (const e of events) {
      out += e.allowed ? `${e.tick} ${e.key} allow\n` : `${e.tick} ${e.key} deny ${e.deniedBy}\n`
    }
    process.stdout.write(out)
  } else {
    const perKey = new Map()
    let totalAllowed = 0
    let totalDenied = 0
    for (const e of events) {
      let s = perKey.get(e.key)
      if (!s) {
        s = { allowed: 0, denied: 0 }
        perKey.set(e.key, s)
      }
      if (e.allowed) {
        s.allowed++
        totalAllowed++
      } else {
        s.denied++
        totalDenied++
      }
    }
    const keys = [...perKey.keys()].sort()
    let out = ''
    for (const key of keys) {
      const s = perKey.get(key)
      out += `${key} allowed=${s.allowed} denied=${s.denied}\n`
    }
    out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
    process.stdout.write(out)
  }
}

main()
"}

