{"file_path":"src/parser.js","content":"/**
 * Parses a limiter file into declared policies, routes and events, enforcing
 * every syntactic and semantic rule from the specification.
 */

const TOKEN_RE = /^[A-Za-z0-9_.\/:-]+$/
const UINT_RE = /^(0|[1-9]\d*)$/

export class ParseError extends Error {}

function isValidToken(s) {
  return TOKEN_RE.test(s)
}

function parseField(str, fieldName, min) {
  if (UINT_RE.test(str)) {
    const value = BigInt(str)
    if (value >= min) return value
  }
  throw new ParseError(`${fieldName} must be an integer of at least ${min}`)
}

/**
 * Parses the whole limiter file text into `{ policies, routes, events }`.
 * `policies` maps name to policy definition, `routes` is the ordered list
 * of route declarations, and `events` is the ordered list of arrivals.
 * Throws `ParseError` with a message describing the first offending line;
 * the caller is expected to prefix it with the line number.
 */
export function parseLimiterFile(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routesByPrefix = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const args = tokens.slice(1)

    try {
      switch (directive) {
        case 'bucket': {
          if (seenEvent) throw new ParseError('declarations must come before the first event')
          if (args.length !== 4) throw new ParseError('expected bucket <name> <capacity> <refill> <per>')
          const [name, capacityStr, refillStr, perStr] = args
          if (!isValidToken(name)) throw new ParseError(`invalid policy name ${name}`)
          const capacity = parseField(capacityStr, 'capacity', 1n)
          const refill = parseField(refillStr, 'refill', 0n)
          const per = parseField(perStr, 'per', 1n)
          if (policies.has(name)) throw new ParseError(`policy ${name} is declared twice`)
          policies.set(name, { type: 'bucket', name, capacity, refill, per, state: new Map() })
          break
        }
        case 'window': {
          if (seenEvent) throw new ParseError('declarations must come before the first event')
          if (args.length !== 3) throw new ParseError('expected window <name> <limit> <span>')
          const [name, limitStr, spanStr] = args
          if (!isValidToken(name)) throw new ParseError(`invalid policy name ${name}`)
          const limit = parseField(limitStr, 'limit', 0n)
          const span = parseField(spanStr, 'span', 1n)
          if (policies.has(name)) throw new ParseError(`policy ${name} is declared twice`)
          policies.set(name, { type: 'window', name, limit, span, state: new Map() })
          break
        }
        case 'route': {
          if (seenEvent) throw new ParseError('declarations must come before the first event')
          if (args.length < 2) throw new ParseError('expected route <prefix> <policy>...')
          const [prefix, ...policyNames] = args
          if (!isValidToken(prefix)) throw new ParseError(`invalid route prefix ${prefix}`)
          for (const name of policyNames) {
            if (!policies.has(name)) throw new ParseError(`unknown policy ${name}`)
          }
          if (routesByPrefix.has(prefix)) throw new ParseError(`prefix ${prefix} is routed twice`)
          const route = { prefix, policies: policyNames }
          routes.push(route)
          routesByPrefix.set(prefix, route)
          break
        }
        case 'event': {
          if (args.length !== 2) throw new ParseError('expected event <tick> <key>')
          const [tickStr, key] = args
          const tick = parseField(tickStr, 'tick', 0n)
          if (!isValidToken(key)) throw new ParseError(`invalid key ${key}`)
          if (lastTick !== null && tick < lastTick) {
            throw new ParseError(`tick ${tick} is before tick ${lastTick}`)
          }
          lastTick = tick
          seenEvent = true
          events.push({ tick, key })
          break
        }
        default:
          throw new ParseError(`unknown directive ${directive}`)
      }
    } catch (err) {
      if (err instanceof ParseError) {
        throw new ParseError(`line ${lineNumber}: ${err.message}`)
      }
      throw err
    }
  }

  return { policies, routes, events }
}
"}

