  const delta = tick - s.lastTick
  const capacityNumerator = policy.capacity * policy.per
  const grown = s.numerator + policy.refill * delta
  s.numerator = grown > capacityNumerator ? capacityNumerator : grown
  s.lastTick = tick
  return s
}

function advanceWindow(policy, key, tick) {
  let s = policy.state.get(key)
  if (!s) {
    s = { ticks: [] }
    policy.state.set(key, s)
  }
  const threshold = tick - policy.span
  let cut = 0
  while (cut < s.ticks.length && s.ticks[cut] <= threshold) cut++
  if (cut > 0) s.ticks = s.ticks.slice(cut)
  return s
}

/** Advances `policy`'s state for `key` to `tick`. */
export function advance(policy, key, tick) {
  return policy.type === 'bucket' ? advanceBucket(policy, key, tick) : advanceWindow(policy, key, tick)
}

/** Reports whether `policy` currently allows a request for `key`. Call `advance` first. */
export function allows(policy, key) {
  const s = policy.state.get(key)
  if (policy.type === 'bucket') return s.numerator >= policy.per
  return BigInt(s.ticks.length) < policy.limit
}

/** Records a request for `key` against `policy`. Only call when `allows` returned true. */
export function record(policy, key, tick) {
  const s = policy.state.get(key)
  if (policy.type === 'bucket') {
    s.numerator -= policy.per
  } else {
    s.ticks.push(tick)
  }
}
"}

{"file_path":"src/simulate.js","content":"import { advance, allows, record } from './policies.js'

/**
 * Finds the route whose prefix matches `key` and is longest among matches,
 * or `null` when no route applies.
 */
function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (!best || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

/**
 * Replays `events` against `policies` and `routes` in order, returning one
 * verdict per event plus per-key and overall totals.
 */
export function simulate({ policies, routes, events }) {
  const verdicts = []
  const perKey = new Map()

  for (const ev of events) {
    const route = findRoute(routes, ev.key)
    const policyNames = route ? route.policies : []
    const policyObjs = policyNames.map((name) => policies.get(name))

    for (const policy of policyObjs) advance(policy, ev.key, ev.tick)

    let denyName = null
    for (let i = 0; i < policyObjs.length; i++) {
      if (!allows(policyObjs[i], ev.key)) {
        denyName = policyNames[i]
        break
      }
    }
    const allowed = denyName === null
    if (allowed) {
      for (const policy of policyObjs) record(policy, ev.key, ev.tick)
    }

    let stat = perKey.get(ev.key)
    if (!stat) {
      stat = { allowed: 0, denied: 0 }
      perKey.set(ev.key, stat)
    }
    if (allowed) stat.allowed++
    else stat.denied++

    verdicts.push({ tick: ev.tick, key: ev.key, allowed, denyName })
  }

  return { verdicts, perKey }
}
"}

