 * Simulates the build graph on a fixed number of workers using greedy list
 * scheduling by priority.
 */

/**
 * @param {string[]} names - all task names, ascending.
 * @param {Map<string, number>} costs
 * @param {Map<string, string[]>} deps
 * @param {Map<string, number>} priority
 * @param {number} workerCount
 * @returns {{ runs: Array<Array<{ name: string, start: number, finish: number }>>, makespan: number }}
 */
export function packWorkers(names, costs, deps, priority, workerCount) {
  const runs = Array.from({ length: workerCount }, () => [])
  const availableAt = new Array(workerCount).fill(0)
  const finish = new Map()
  const scheduled = new Set()
  let currentTime = 0

  const findFreeWorker = () => {
    for (let i = 0; i < workerCount; i++) {
      if (availableAt[i] <= currentTime) {
        return i
      }
    }
    return -1
  }

  const findReadyTask = () => {
    let best = null
    for (const name of names) {
      if (scheduled.has(name)) {
        continue
      }
      const dependencies = deps.get(name) ?? []
      const ready = dependencies.every((dependency) => {
        const dependencyFinish = finish.get(dependency)
        return dependencyFinish !== undefined && dependencyFinish <= currentTime
      })
      if (!ready) {
        continue
      }
      if (best === null || priority.get(name) > priority.get(best)) {
        best = name
      }
    }
    return best
  }

  while (scheduled.size < names.length) {
    let progressed = true
    while (progressed) {
      progressed = false
      const workerIndex = findFreeWorker()
      if (workerIndex === -1) {
        break
      }
      const task = findReadyTask()
      if (task === null) {
        break
      }
      const start = currentTime
      const taskFinish = start + costs.get(task)
      runs[workerIndex].push({ name: task, start, finish: taskFinish })
      availableAt[workerIndex] = taskFinish
      finish.set(task, taskFinish)
      scheduled.add(task)
      progressed = true
    }
    if (scheduled.size >= names.length) {
      break
    }
    let next = Infinity
    for (const a of availableAt) {
      if (a > currentTime) {
        next = Math.min(next, a)
      }
    }
    currentTime = next
  }

  let makespan = 0
  for (const f of finish.values()) {
    makespan = Math.max(makespan, f)
  }

  return { runs, makespan }
}
"}

