/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph } from './parse.js'
import { checkForCycle, computeTiming, computePriority } from './graph.js'
import { packWorkers } from './schedule.js'
import { CliError, CycleError } from './errors.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKER_RE = /^[1-9][0-9]*$/

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKER_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE)
}

function runWaves(names, costs, deps) {
  checkForCycle(names, deps)
  const { depth, start, finish } = computeTiming(names, costs, deps)

  const waves = []
  for (const name of names) {
    const d = depth.get(name)
    if (!waves[d]) {
      waves[d] = []
    }
    waves[d].push(name)
  }

  const lines = []
  for (let i = 0; i < waves.length; i++) {
    lines.push(`wave ${i}: ${waves[i].join(' ')}`)
  }
  let total = 0
  for (const f of finish.values()) {
    total = Math.max(total, f)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runExplain(names, costs, deps) {
  checkForCycle(names, deps)
  const { depth, start, finish } = computeTiming(names, costs, deps)

  const lines = []
  for (const name of names) {
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  }
  let total = 0
  for (const f of finish.values()) {
    total = Math.max(total, f)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runPack(names, costs, deps, workerCount) {
  checkForCycle(names, deps)
  const priority = computePriority(names, costs, deps)
  const { runs, makespan } = packWorkers(names, costs, deps, priority, workerCount)

  const lines = []
  for (let i = 0; i < workerCount; i++) {
    const entries = runs[i].map((task) => ` ${task.name}@${task.start}-${task.finish}`).join('')
    lines.push(`worker ${i}:${entries}`)
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = await readStdin()
  const { order, costs, deps } = parseGraph(input)
  const names = [...order].sort()

  let output
  if (args.mode === 'waves') {
    output = runWaves(names, costs, deps)
  } else if (args.mode === 'explain') {
    output = runExplain(names, costs, deps)
  } else {
    output = runPack(names, costs, deps, args.workers)
  }
  process.stdout.write(output)
}

main().catch((error) => {
  if (error instanceof CycleError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(3)
  }
  if (error instanceof CliError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(2)
  }
  throw error
})
"}

