 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 *
 * Every function here works on plain objects with the shape
 * `{ scheme, authority, path, query, fragment }`, where `path` is always a
 * string and the other four fields are either a string or `null` to mark an
 * absent component (as opposed to one that is present but empty).
 */

const UNRESERVED = /[A-Za-z0-9\-._~]/
const HEX_PAIR = /^[0-9a-fA-F]{2}$/
const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Raised when a `%` is not followed by two hexadecimal digits. */
export class PercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function asciiLower(str) {
  return str.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

/** Parse a URI reference into its five generic components. */
export function parseUri(text) {
  let rest = text
  let scheme = null

  const colonIdx = rest.indexOf(':')
  if (colonIdx !== -1 && !/[/?#]/.test(rest.slice(0, colonIdx))) {
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (const ch of ['/', '?', '#']) {
      const i = rest.indexOf(ch)
      if (i !== -1 && i < end) end = i
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let pathEnd = rest.length
  const qMark = rest.indexOf('?')
  const hMark = rest.indexOf('#')
  if (qMark !== -1) pathEnd = Math.min(pathEnd, qMark)
  if (hMark !== -1) pathEnd = Math.min(pathEnd, hMark)
  const path = rest.slice(0, pathEnd)
  rest = rest.slice(pathEnd)

  let query = null
  if (rest.startsWith('?')) {
    const fMark = rest.indexOf('#')
    if (fMark === -1) {
      query = rest.slice(1)
      rest = ''
    } else {
      query = rest.slice(1, fMark)
      rest = rest.slice(fMark)
    }
  }

  let fragment = null
  if (rest.startsWith('#')) fragment = rest.slice(1)

  return { scheme, authority, path, query, fragment }
}

/** Split an authority into its userinfo, host and port pieces. */
export function parseAuthority(authority) {
  let userinfo = null
  let hostport = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    hostport = authority.slice(atIdx + 1)
  }

  const bracketIdx = hostport.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx + 1
  const colonIdx = hostport.indexOf(':', searchFrom)

  let host = hostport
  let port = null
  if (colonIdx !== -1) {
    host = hostport.slice(0, colonIdx)
    port = hostport.slice(colonIdx + 1)
  }

  return { userinfo, host, port }
}

function serializeAuthority({ userinfo, host, port }) {
  let s = ''
  if (userinfo !== null) s += userinfo + '@'
  s += host
  if (port !== null) s += ':' + port
  return s
}

function serialize({ scheme, authority, path, query, fragment }) {
  let s = ''
  if (scheme !== null) s += scheme + ':'
  if (authority !== null) s += '//' + authority
  s += path
  if (query !== null) s += '?' + query
  if (fragment !== null) s += '#' + fragment
  return s
