 * Uppercase the hex digits of every `%XX` triplet in `str` and decode the
 * ones that spell an unreserved character. Throws `PercentEncodingError`
 * when a `%` is not followed by two hexadecimal digits.
 */
function normalizePercentEncodings(str, component) {
  let result = ''
  for (let i = 0; i < str.length; i++) {
    const ch = str[i]
    if (ch !== '%') {
      result += ch
      continue
    }
    const hex = str.slice(i + 1, i + 3)
    if (!HEX_PAIR.test(hex)) throw new PercentEncodingError(component)
    const upper = hex.toUpperCase()
    const decoded = String.fromCharCode(parseInt(upper, 16))
    result += UNRESERVED.test(decoded) ? decoded : '%' + upper
    i += 2
  }
  return result
