      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) idx = input.length
      output += input.slice(0, idx)
      input = input.slice(idx)
    }
  }
  return output
}

/** Apply every RFC 3986 normalization step, in the order the spec lists them. */
export function normalizeParsed(parsed) {
  let { scheme, authority, path, query, fragment } = parsed

  if (scheme !== null) scheme = asciiLower(scheme)

  let userinfo = null
  let host = null
  let port = null
  if (authority !== null) ({ userinfo, host, port } = parseAuthority(authority))

  path = normalizePercentEncodings(path, 'path')
  if (userinfo !== null) userinfo = normalizePercentEncodings(userinfo, 'userinfo')
  if (host !== null) host = normalizePercentEncodings(host, 'host')
  if (query !== null) query = normalizePercentEncodings(query, 'query')
  if (fragment !== null) fragment = normalizePercentEncodings(fragment, 'fragment')

  if (host !== null) host = asciiLower(host)

  if (authority !== null) {
    const defaultPort = scheme !== null ? DEFAULT_PORTS[scheme] : undefined
    if (port !== null && (port === '' || port === defaultPort)) port = null
    authority = serializeAuthority({ userinfo, host, port })
  }

  path = removeDotSegments(path)

  if (authority !== null && path === '') path = '/'

  return serialize({ scheme, authority, path, query, fragment })
}

/** Normalize a URI reference given as text. */
export function normalize(text) {
  return normalizeParsed(parseUri(text))
}

function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/** Resolve reference components `ref` against base components `base` per RFC 3986 5.2.2. */
export function resolveParsed(base, ref) {
  let scheme
  let authority
  let path
  let query

  if (ref.scheme !== null) {
    scheme = ref.scheme
    authority = ref.authority
    path = removeDotSegments(ref.path)
    query = ref.query
  } else if (ref.authority !== null) {
    scheme = base.scheme
    authority = ref.authority
    path = removeDotSegments(ref.path)
    query = ref.query
  } else if (ref.path === '') {
    scheme = base.scheme
    authority = base.authority
    path = base.path
    query = ref.query !== null ? ref.query : base.query
  } else {
    scheme = base.scheme
    authority = base.authority
    path = ref.path.startsWith('/')
      ? removeDotSegments(ref.path)
      : removeDotSegments(mergePaths(base, ref.path))
    query = ref.query
  }

  return { scheme, authority, path, query, fragment: ref.fragment }
}

/** Resolve a reference given as text against a base given as text, then normalize the result. */
export function resolve(baseText, refText) {
  const base = parseUri(baseText)
  const ref = parseUri(refText)
  return normalizeParsed(resolveParsed(base, ref))
}
"}

