      } else if (err instanceof RecordError) {
        process.stderr.write(`error: ${err.message}\n`)
      } else {
        throw err
      }
      process.exit(2)
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

