{"file_path":"src/deps.js","content":"/**
 * Collects the distinct addressable cells a formula names directly, with
 * ranges expanded, for `deps` mode.
 */

import { classifyContent } from './evaluate.js'
import { makeAddress } from './address.js'

/** Returns the sorted, deduplicated list of addressable cells the given raw
 * cell content names directly (empty for a literal or an unparsed formula). */
export function collectDeps(content) {
  const { kind, ast } = classifyContent(content)
  const names = new Set()
  if (kind === 'formula' && ast !== null) walk(ast, names)
  return names
}

function walk(node, names) {
  switch (node.type) {
    case 'Num':
    case 'Bool':
      return
    case 'Cell':
      if (node.valid) names.add(node.address)
      return
    case 'Unary':
      walk(node.expr, names)
      return
    case 'Bin':
      walk(node.left, names)
      walk(node.right, names)
      return
    case 'Call':
      for (const arg of node.args) walkArg(arg, names)
      return
    default:
      throw new Error(`unreachable node type ${node.type}`)
  }
}

function walkArg(node, names) {
  if (node.type === 'Range') {
    if (!node.valid) return
    const cmin = Math.min(node.col1, node.col2)
    const cmax = Math.max(node.col1, node.col2)
    const rmin = Math.min(node.row1, node.row2)
    const rmax = Math.max(node.row1, node.row2)
    for (let c = cmin; c <= cmax; c++) {
      for (let r = rmin; r <= rmax; r++) names.add(makeAddress(c, r))
    }
    return
  }
  walk(node, names)
}
"}

